<script module lang="ts">
/**
 * Multi-line text entry (`design/components/textarea.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/textarea.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  agentFill,
  agentMember,
  fitTextarea,
  joinSlot,
  useControlRef,
  watchEffect,
  type ControlRef,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/textarea.module.css'

export type TextareaResize = NonNullable<TextareaProps['resize']>

export interface TextareaProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  /**
   * Names the field from a label elsewhere on the page, such as `SettingsRow`'s row label, which
   * is one label for a whole row rather than one per control.
   */
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * Native passthrough, as in Input. For surfaces that have already moved the user, such as a
   * dialog's first field. Never use it to take focus when a page loads.
   */
  autoFocus?: boolean
  /**
   * Grows with its content. Opt-in, because a field that grows while typing moves everything
   * below it, and the form decides that, not the field. Implies `resize: 'none'`, because a box
   * that resizes itself and can also be dragged would have two owners for one height.
   */
  autosize?: boolean
  /**
   * The native `<textarea>`, like Input's `controlRef`, for an application binding that must
   * read or restore a caret or selection. Merged with the autosizer's ref, so both get the same
   * node, and `null` on unmount.
   */
  controlRef?: ControlRef<HTMLTextAreaElement | null>
  defaultValue?: string
  disabled?: boolean
  id?: string
  invalid?: boolean
  maxLength?: number
  name?: string
  /**
   * For touched validation, as in Input: apps mark a field dirty when focus leaves.
   */
  onBlur?: (event: FocusEvent) => void
  onChange?: (value: string, event: Event) => void
  /**
   * Native passthrough for IME composition end. `event.data` is the committed text.
   */
  onCompositionEnd?: (event: CompositionEvent) => void
  /**
   * Native passthrough for IME composition start. Composition events arrive as the platform
   * fires them, never suppressed and never repeated as a second change.
   */
  onCompositionStart?: (event: CompositionEvent) => void
  onFocus?: (event: FocusEvent) => void
  /**
   * Native passthrough. Fires when the caret or range moves, by keyboard or pointer.
   * `selectionStart`, `selectionEnd` and `selectionDirection` are on `event.currentTarget`. The
   * member never moves the selection itself.
   */
  onSelect?: (event: Event) => void
  placeholder?: string
  readOnly?: boolean
  /**
   * Never horizontal, because column width belongs to the layout, not the user.
   */
  resize?: 'vertical' | 'none'
  /**
   * The height, in line units.
   */
  rows?: number
  value?: string
}
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  autoFocus = false,
  autosize = false,
  controlRef,
  defaultValue,
  disabled = false,
  id: idOwn,
  invalid: invalidOwn = false,
  maxLength,
  name,
  onBlur,
  onChange,
  onCompositionEnd,
  onCompositionStart,
  onFocus,
  onSelect,
  placeholder,
  readOnly = false,
  resize,
  rows = 4,
  value,
}: TextareaProps = $props()
const joined = joinSlot(undefined, () => ({ disabled: disabled, name: name }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
// svelte-ignore state_referenced_locally
let draft = $state(defaultValue ?? '')
let control = $state<HTMLTextAreaElement | null>(null)
const resizing = $derived(resize ?? (autosize ? 'none' : 'vertical'))
useControlRef(
  () => controlRef,
  () => control,
)
const effect1 = () => {
  autosize && control && fitTextarea(control)
}
watchEffect(effect1, { watch: () => [value, defaultValue, autosize] })
const effect2 = () => {
  autoFocus && control?.focus()
}
watchEffect(effect2)
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'Textarea',
    element: () => control,
    state: () => ({
      value: value ?? draft,
      disabled: disabled,
      invalid: invalid,
      readonly: readOnly,
    }),
    actions: {
      fill: {
        argument: 'text',
        run: (value) =>
          (() => {
            if (readOnly) throw new Error('The field is read-only.')
            agentFill(control, value)
          })(),
      },
      clear: () =>
        (() => {
          if (readOnly) throw new Error('The field is read-only.')
          agentFill(control, '')
        })(),
    },
  })
  release3 = () => {
    ran()
  }
}
watchEffect(effect3)
onDestroy(() => release3?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<textarea
    bind:this={control}
    class={styles.textarea}
    {id}
    {rows}
    value={value ?? draft}
    {placeholder}
    {name}
    maxlength={maxLength}
    {disabled}
    readonly={readOnly}
    aria-label={ariaLabel}
    aria-labelledby={ariaLabelledby}
    aria-describedby={ariaDescribedby}
    aria-required={ariaRequired}
    aria-invalid={(invalid) ? true : undefined}
    data-resize={resizing}
    data-autosize={(autosize) ? '' : undefined}
    data-invalid={(invalid) ? '' : undefined}
    data-disabled={(disabled) ? '' : undefined}
    data-readonly={(readOnly) ? '' : undefined}
    data-member="textarea"
    oninput={(event) => { (draft = control?.value ?? '', autosize && control && fitTextarea(control), onChange?.(draft, event)) }}
    onblur={(event) => { onBlur?.(event) }}
    onfocus={(event) => { onFocus?.(event) }}
    onselect={(event) => { onSelect?.(event) }}
    oncompositionstart={(event) => { onCompositionStart?.(event) }}
    oncompositionend={(event) => { onCompositionEnd?.(event) }}
  ></textarea
>{/if
}{@render joined.end?.()}
